import glob
import numpy as np
import os

files = glob.glob('/root/data/*.npz')
count = 0
for f in files:
    try:
        d = np.load(f)
        if 'event_time' in d and 'start_time' in d and 'distance_km' in d:
            count += 1
    except:
        pass
print(f"Files with metadata: {count}/{len(files)}")
